from datetime import datetime

def validate_date_format(date_str):
    try:
        datetime.strptime(date_str, '%Y-%m-%d')
        return True
    except ValueError:
        return False

# Example usage
print(validate_date_format('2022-01-01'))  # Should print: True
print(validate_date_format('01-01-2022'))  # Should print: False
